+
+function cellsForZone(zone: VisualZone, bins: readonly Bin[], scenario: Scenario): HeatmapCell[] {
+  const columns = Math.ceil(Math.sqrt(bins.length));
+  const rows = Math.ceil(bins.length / columns);
+  const padding = 48;
+  const gap = 12;
+  const cellWidth = (zone.width - padding * 2 - gap * (columns - 1)) / columns;
+  const cellHeight = (zone.height - padding - 24 - gap * (rows - 1)) / rows;
+
+  return bins.map((bin, index) => {
+    const column = index % columns;
+    const row = Math.floor(index / columns);
+    const quantity = totalUnitsInBin(scenario.inventory, bin.id);
+    const stock = stockLinesForBin(scenario.inventory, bin.id);
+    return {
+      binId: bin.id,
+      zoneId: bin.zoneId,
+      code: bin.code,
+      x: zone.x + padding + column * (cellWidth + gap),
+      y: zone.y + 42 + row * (cellHeight + gap),
+      width: cellWidth,
+      height: cellHeight,
+      capacity: bin.capacity,
+      quantity,
+      occupancyRatio: quantity / bin.capacity,
+      status: statusFor(quantity, bin.capacity),
+      stock,
+    };
+  });
+}
+
+function buildAisles(): VisualAisle[] {
+  return [
+    {
+      id: "aisle-main",
+      label: "Pasillo central",
+      x: CANVAS.margin + CANVAS.zoneWidth + 24,
+      y: CANVAS.margin,
+      width: 80,
+      height: CANVAS.zoneHeight * 2 + CANVAS.gapY,
+    },
+    {
+      id: "aisle-cross",
+      label: "Pasillo transversal",
+      x: CANVAS.margin,
+      y: CANVAS.margin + CANVAS.zoneHeight + 24,
+      width: CANVAS.zoneWidth * 2 + CANVAS.gapX,
+      height: 40,
+    },
+  ];
+}
+
+export function buildControlTowerVisual(scenario: Scenario): ControlTowerVisual {
+  const zones = scenario.layout.zones.map(zoneFrame);
+  const heatmapCells = zones.flatMap((zone) => {
+    const bins = scenario.layout.bins.filter((bin) => bin.zoneId === zone.id);
+    return cellsForZone(zone, bins, scenario);
+  });
+  const aisles = buildAisles();
+  const textLabels = [
+    ...zones.map((zone) => zone.name),
+    ...aisles.map((aisle) => aisle.label),
+    ...heatmapCells.map((cell) => `${cell.code} ${STATUS_LABELS[cell.status]}`),
+    ...LEGEND.map((item) => item.label),
+  ];
+
+  return {
+    width: CANVAS.width,
+    height: CANVAS.height,
+    zones,
+    aisles,
+    heatmapCells,
+    legend: LEGEND,
+    textLabels,
+    svgElementCount: zones.length + aisles.length + heatmapCells.length + textLabels.length + LEGEND.length,
+  };
+}
+
+export function visualCapabilities(visual: ControlTowerVisual) {
+  return {
+    svgElements: visual.svgElementCount,
+    heatmapCells: visual.heatmapCells.length,
+    textLabels: visual.textLabels.length,
+  };
+}
